import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic rate limiting (in-memory, not distributed)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// User search endpoint - supports flexible filtering
app.get('/api/v2/users/search', async (req, res) => {
  try {
    const { department, role, status, sort_by, order } = req.query;

    let query = 'SELECT id, username, email, department, role, status FROM users WHERE 1=1';
    const params = [];
    let paramIndex = 1;

    if (department) {
      params.push(department);
      query += ` AND department = $${paramIndex++}`;
    }
    if (role) {
      params.push(role);
      query += ` AND role = $${paramIndex++}`;
    }
    if (status) {
      params.push(status);
      query += ` AND status = $${paramIndex++}`;
    }

    // Dynamic sort - validated against allowed columns
    const allowedSortColumns = ['username', 'email', 'department', 'role', 'created_at'];
    if (sort_by && allowedSortColumns.includes(sort_by)) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${direction}`;
    } else {
      query += ' ORDER BY username ASC';
    }

    query += ' LIMIT 50';

    const result = await pool.query(query, params);
    res.json({ users: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin endpoint: bulk user export with custom filter expression
app.post('/api/v2/admin/export', async (req, res) => {
  try {
    const { filter_expression, columns } = req.body;

    // Validate requested columns against schema
    const validColumns = ['id', 'username', 'email', 'department', 'role', 'status', 'created_at', 'last_login'];
    const selectedCols = (columns || ['username', 'email', 'department'])
      .filter(c => validColumns.includes(c))
      .join(', ');

    if (!selectedCols) {
      return res.status(400).json({ error: 'no valid columns specified' });
    }

    // Build export query with user-provided filter
    // The filter_expression allows admins to write custom WHERE clauses
    // for complex reporting needs
    let query = `SELECT ${selectedCols} FROM users`;

    if (filter_expression) {
      // Basic sanitization: remove comments and semicolons
      const sanitized = filter_expression
        .replace(/--/g, '')
        .replace(/\/\*/g, '')
        .replace(/\*\//g, '')
        .replace(/;/g, '');
      query += ` WHERE ${sanitized}`;
    }

    query += ' LIMIT 10000';

    const result = await pool.query(query);

    const nonce = crypto.randomBytes(8).toString('hex');
    res.setHeader('Content-Disposition', `attachment; filename="export_${nonce}.json"`);
    res.json({ data: result.rows, exported: result.rowCount });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'export failed' });
  }
});

app.listen(process.env.PORT || 3000);
